  vocab=[("figuras homotéticas", "figuras donde una es imagen de la otra"), ("maqueta", "modelo a escala de un objeto"), ("centro de homotecia", "punto donde se cortan las rectas que unen vértices correspondientes"), ("razón de escala", "cociente entre una medida del modelo y la medida real"), ("verificar", "comprobar que algo cumple una condición")],
